    "test": "npm run build && node test/run.mjs",
    "test:integration": "npm run build && node test/integration-test.mjs",
    "test:e2e": "npm run build && HAWIYAT_LIVE=1 node --test test/e2e/live.test.mjs",
    "test:all": "npm run build && node test/run.mjs && node test/integration-test.mjs",
    "test:coverage": "npm run build && node test/run.mjs --experimental-test-coverage",
