#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { setDebug } from './utils/logger.js';
import { CLI_VERSION } from './core/version.js';
const VALID_COMMANDS = ['install', 'uninstall', 'update', 'rollback', 'auth', 'showcase'];
const LOGO = `
                 ++=
              +++++=====
          +++++++++========
       ++++++++++++===========
    +++++++++++++++==============
 ++++++++++++++++++=================
 ++++++++++++++++++#################
 ++++++++++++++++++#################**
 ++++++++++++++++++#################*******
    +++++++++++++++##############************+++
       ++++++++++++###########***************+++++
           ++++++++########**************
              +++++#######******
                 ++####`;
const SPLASH = `
${LOGO}

  Hawiyat Kit v${CLI_VERSION}
  One-command setup for Claude Code, OpenCode, pi, DeepSeek Harness, Codex, and Claude Desktop.

  npx @hawiyat-team/hawiyat-claude install --token <your-token>

  install · uninstall · update · rollback · auth · showcase
  Run with --help for details.
`;
const USAGE = `
Usage:
  hawiyat-claude <command> [options]

Commands:
  install    Configure Claude Code, OpenCode, pi, DeepSeek Harness, Codex, or Claude Desktop
  uninstall  Remove Hawiyat configuration; restore from backup (Codex files handled automatically)
  update     Apply manifest deltas (new skills, updated plugins, Codex config refresh)
  rollback   Restore from a backup (Claude, OpenCode, and Codex files)
  auth       Log in to Hawiyat, show auth status, or log out
  showcase   Animated usage tour with the commands clients need

Global Flags:
  --help, -h    Show this message
  --debug       Verbose output with stack traces
  --yes, -y     Skip all prompts (non-interactive mode)
  --version     Show version number
  --no-animations  Disable spinner, scan line, and showcase animation
  --project     Target project-local .claude/ instead of ~/.claude/
  --codex       Configure Codex only (skips Claude Code and OpenCode)
  --codex-desktop  Configure Codex Desktop only (Windows and macOS; same files as --codex)
  --claude-desktop Configure Claude Desktop only (local 3P profile, with an import fallback)

Install Flags:
  --interactive, -i   Pick harnesses interactively (requires a TTY)
  --no-tui            Use the numeric harness menu instead of the arrow-key TUI
  --targets <list>    Comma-separated: claude,opencode,pi,deepseek,codex,claude-desktop (default: claude,opencode)
  --pi                Configure pi only
  --deepseek          Configure DeepSeek Harness (dsh) only
  --models <a,b,c>    Models to expose (Codex picker, pi, dsh, OpenCode)
  --no-discovery      Skip auto-discovery of models from the Hawiyat gateway
  --model <name>      Default model
  --bootstrap-client-id <id>  Claude Desktop: write an OIDC bootstrap anchor instead of a key
  --bootstrap-base-url <url>  Bootstrap host, default https://dash.hawiyat.cloud
  --extensions        Install the official Hawiyat extension for pi/OpenCode
  --no-extensions     Write the raw provider config (skip the extension)

Auth Flags:
  --no-browser        Do not open the browser during auth login
  --targets <list>    After login, configure these harnesses (claude,opencode,pi,deepseek,codex,claude-desktop)
  --claude            After login, configure Claude Code
  --opencode          After login, configure OpenCode
  --pi                After login, configure pi
  --deepseek          After login, configure DeepSeek Harness (dsh)
  --codex             After login, configure Codex CLI
  --codex-desktop     After login, configure Codex Desktop
  --claude-desktop    After login, configure Claude Desktop
  --interactive, -i   After login, pick harnesses from the TTY menu
  --no-tui            With -i, use the numeric menu instead of the arrow-key TUI
  --install           After login, configure the default harnesses (claude,opencode)
  --no-install        Log in only; do not offer harness setup
  --revoke            auth logout: revoke the key on the dashboard first
`;
function showHelp() {
    console.log(SPLASH);
    console.log(USAGE);
}
async function main() {
    const { values, positionals } = parseArgs({
        args: process.argv.slice(2),
        options: {
            help: { type: 'boolean', short: 'h' },
            version: { type: 'boolean' },
            'no-animations': { type: 'boolean' },
            debug: { type: 'boolean' },
            yes: { type: 'boolean', short: 'y' },
        },
        allowPositionals: true,
        strict: false,
    });
    if (values.debug) {
        setDebug(true);
    }
    if (values['no-animations']) {
        process.env.NO_ANIMATIONS = '1';
    }
    if (values.help) {
        showHelp();
        process.exit(0);
    }
    if (values.version) {
        console.log(SPLASH);
        process.exit(0);
    }
    const command = positionals[0];
    // No command on an interactive terminal: run the install wizard.
    if (!command && process.stdin.isTTY) {
        const { default: installCommand } = (await import('./commands/install.js'));
        await installCommand({ interactive: true });
        return;
    }
    if (!command || !VALID_COMMANDS.includes(command)) {
        console.error(SPLASH);
        console.error('hawiyat-claude: unknown command "' + (command || '') + '"');
        console.error('Try hawiyat-claude --help for usage.');
        process.exit(1);
    }
    const { default: cmd } = (await import(`./commands/${command}.js`));
    await cmd(values);
}
main().catch((err) => {
    if (process.argv.includes('--debug')) {
        console.error('hawiyat-claude: unexpected error', err);
    }
    else {
        console.error('hawiyat-claude: unexpected error:', err.message);
    }
    process.exit(1);
});
//# sourceMappingURL=cli.js.map

import fs from 'node:fs/promises';
import path from 'node:path';
export const SUPERPOWERS_PLUGIN_ID = 'superpowers@claude-plugins-official';
export const SUPERPOWERS_PLUGIN_VERSION = '5.1.0';
export const PLUGIN_SOURCE_MARKETPLACE = 'claude-plugins-official';
/**
 * Compare two semver version strings numerically.
 * Splits on '.' and compares each part as an integer.
 *
 * @param a - First version
 * @param b - Second version
 * @returns -1 if a < b, 0 if a === b, 1 if a > b
 */
export function compareVersions(a, b) {
    const partsA = a.split('.').map(Number);
    const partsB = b.split('.').map(Number);
    const len = Math.max(partsA.length, partsB.length);
    for (let i = 0; i < len; i++) {
        const numA = i < partsA.length ? partsA[i] : 0;
        const numB = i < partsB.length ? partsB[i] : 0;
        if (numA > numB)
            return 1;
        if (numA < numB)
            return -1;
    }
    return 0;
}
/**
 * Read and parse the installed plugins JSON file.
 *
 * @param filePath - Path to the installed_plugins.json file
 * @returns Parsed plugins object
 * @throws {Error} If the file contains invalid JSON
 */
export async function readPlugins(filePath) {
    let raw;
    try {
        raw = await fs.readFile(filePath, 'utf-8');
    }
    catch (err) {
        if (err.code === 'ENOENT') {
            return { installedPlugins: [] };
        }
        throw err;
    }
    try {
        return JSON.parse(raw);
    }
    catch {
        throw new Error(`Invalid JSON in plugins file: ${filePath}`);
    }
}
/**
 * Write the plugins object to disk atomically.
 * Creates parent directories if they do not exist.
 *
 * @param filePath - Path to the installed_plugins.json file
 * @param pluginsObj - Plugins object to write
 */
export async function writePlugins(filePath, pluginsObj) {
    const dir = path.dirname(filePath);
    await fs.mkdir(dir, { recursive: true });
    const tmpPath = filePath + '.tmp';
    const data = JSON.stringify(pluginsObj, null, 2);
    await fs.writeFile(tmpPath, data, 'utf-8');
    await fs.rename(tmpPath, filePath);
}
function createPluginEntry(marketplaceIdentifier, version) {
    return {
        marketplaceIdentifier,
        version,
        installDate: new Date().toISOString(),
        source: {
            type: 'marketplace',
            marketplaceIdentifier: PLUGIN_SOURCE_MARKETPLACE,
        },
    };
}
/**
 * Install or update a plugin in the installed_plugins.json file.
 *
 * - If the same version is already installed, the call is a no-op (idempotent).
 * - If a newer version is already installed, the call is skipped (no downgrade).
 * - If an older version is installed, the plugin is upgraded.
 *
 * @param filePath - Path to the installed_plugins.json file
 * @param marketplaceIdentifier - Plugin identifier
 * @param version - Plugin version to install
 * @returns Updated plugins object
 */
export async function installPlugin(filePath, marketplaceIdentifier, version) {
    const pluginsObj = await readPlugins(filePath);
    const existing = isPluginInstalled(pluginsObj, marketplaceIdentifier);
    if (existing) {
        const cmp = compareVersions(version, existing.version);
        if (cmp === 0) {
            return pluginsObj;
        }
        if (cmp < 0) {
            return pluginsObj;
        }
        existing.version = version;
        existing.installDate = new Date().toISOString();
        existing.source = {
            type: 'marketplace',
            marketplaceIdentifier: PLUGIN_SOURCE_MARKETPLACE,
        };
    }
    else {
        const entry = createPluginEntry(marketplaceIdentifier, version);
        pluginsObj.installedPlugins.push(entry);
    }
    await writePlugins(filePath, pluginsObj);
    return pluginsObj;
}
/**
 * Remove a plugin from the installed_plugins.json file.
 *
 * @param filePath - Path to the installed_plugins.json file
 * @param marketplaceIdentifier - Plugin identifier to remove
 * @returns True if a plugin was removed, false otherwise
 */
export async function removePlugin(filePath, marketplaceIdentifier) {
    const pluginsObj = await readPlugins(filePath);
    const initialLength = pluginsObj.installedPlugins.length;
    pluginsObj.installedPlugins = pluginsObj.installedPlugins.filter((p) => p.marketplaceIdentifier !== marketplaceIdentifier);
    if (pluginsObj.installedPlugins.length === initialLength) {
        return false;
    }
    await writePlugins(filePath, pluginsObj);
    return true;
}
/**
 * Check if a plugin is installed.
 *
 * @param pluginsObj - Plugins object (must have an installedPlugins array)
 * @param marketplaceIdentifier - Plugin identifier
 * @returns The plugin entry if found, null otherwise
 */
export function isPluginInstalled(pluginsObj, marketplaceIdentifier) {
    if (!pluginsObj || !Array.isArray(pluginsObj.installedPlugins)) {
        return null;
    }
    return pluginsObj.installedPlugins.find((p) => p.marketplaceIdentifier === marketplaceIdentifier) || null;
}
